{
  "name": "@forceuser/opencode-img",
  "version": "0.1.7",
  "description": "OpenCode plugin that routes images from text-only models to an @img vision subagent.",
  "type": "module",
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "author": "",
  "homepage": "https://github.com/forceuser/opencode-img#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/forceuser/opencode-img.git"
  },
  "bugs": {
    "url": "https://github.com/forceuser/opencode-img/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "vision",
    "image",
    "multimodal",
    "deepseek",
    "kimi"
  ],
  "main": "./src/server.js",
  "bin": {
    "opencode-img": "./bin/opencode-img.js"
  },
  "exports": {
    ".": "./src/server.js",
    "./server": {
      "import": "./src/server.js",
      "config": {
        "custom": true
      }
    },
    "./tui": {
      "import": "./src/tui.js",
      "config": {
        "custom": true
      }
    }
  },
  "files": [
    "bin",
    "src",
    "template",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "check": "node --check src/opencode-paths.js && node --check src/server.js && node --check src/tui.js && node --check bin/opencode-img.js",
    "pack:dry": "npm pack --dry-run"
  },
  "engines": {
    "node": ">=20",
    "opencode": ">=1.17.0"
  }
}
